 const [aiStatus,setAiStatus]=useState<AiStatus>(EMPTY_AI_STATUS);const [aiEnabled,setAiEnabled]=useState(false);const [aiPending,setAiPending]=useState<'draft'|'chat'|null>(null);const [aiError,setAiError]=useState('');const [failedChat,setFailedChat]=useState('');
 const [aiProposal,setAiProposal]=useState<{draft:Draft;original:string;fingerprint:string}|null>(null);
 const workspaceRef=useRef(workspace);workspaceRef.current=workspace;const selectionRef=useRef(selectedId);selectionRef.current=selectedId;const aiRequestRef=useRef<AbortController|null>(null);
 useEffect(()=>{const controller=new AbortController();getAiStatus(controller.signal).then(status=>{if(!controller.signal.aborted){setAiStatus(status);setAiEnabled(status.configured);}}).catch(()=>{});return()=>{controller.abort();aiRequestRef.current?.abort();aiRequestRef.current=null;};},[]);
 function cancelAi(){aiRequestRef.current?.abort();aiRequestRef.current=null;setAiPending(null);setAiError('AI request cancelled. No answer was changed.');}
 function changeAiStatus(status:AiStatus){cancelAi();setAiError('');setFailedChat('');setAiStatus(status);if(!status.configured)setAiEnabled(false);}
 function changeAiEnabled(enabled:boolean){cancelAi();setAiError('');setFailedChat('');setAiEnabled(enabled);}
 function prepareDraft(questionId:string,startingPoint?:Draft){if(startingPoint||!aiEnabled||!aiStatus.configured){makeDraft(questionId,startingPoint);return;}const existing=workspaceRef.current.drafts.find(d=>d.questionId===questionId);if(existing){showCard('draft',existing.id);notify('Opened your existing answer. Choose Suggest with AI for a new version.');return;}void generateAiDraft(questionId);}
 async function generateAiDraft(questionId:string,existingId?:string){
  if(aiRequestRef.current)return;if(!aiStatus.configured){setModal('ai-settings');return;}
  const initial=workspaceRef.current;const question=initial.questions.find(q=>q.id===questionId);if(!question)return;
  const original=existingId?initial.drafts.find(d=>d.id===existingId):undefined;const originalText=JSON.stringify(original);const fingerprint=aiEvidenceFingerprint(initial,question.text);
  const controller=new AbortController();aiRequestRef.current=controller;setAiPending('draft');setAiError('');
  try{const request=buildAiRequest('draft',question.text,initial);const response=await requestAiAnswer(request,controller.signal);if(aiRequestRef.current!==controller)return;
   const current=workspaceRef.current;const nowQuestion=current.questions.find(q=>q.id===questionId);const nowDraft=existingId?current.drafts.find(d=>d.id===existingId):undefined;
   if(!nowQuestion||fingerprint!==aiEvidenceFingerprint(current,nowQuestion.text)||JSON.stringify(nowDraft)!==originalText||(!existingId&&current.drafts.some(d=>d.questionId===questionId)))throw new Error('The question, evidence or answer changed while AI was working. Request a fresh suggestion; your edits are preserved.');
   const fresh=applyAiDraft(response,nowQuestion,current,request);
   if(original){setAiProposal({draft:{...fresh,id:original.id,createdAt:original.createdAt},original:originalText,fingerprint});setModal('ai-preview');}
   else makeDraft(questionId,undefined,fresh);
  }catch(error){if(aiRequestRef.current===controller)setAiError(error instanceof Error?error.message:'AI could not prepare this answer. Try again or use a local template.');}
  finally{if(aiRequestRef.current===controller){aiRequestRef.current=null;setAiPending(null);}}
 }
 function applyAiProposal(){if(!aiProposal)return;const current=workspaceRef.current;const original=current.drafts.find(d=>d.id===aiProposal.draft.id);const question=current.questions.find(q=>q.id===aiProposal.draft.questionId);if(!question||JSON.stringify(original)!==aiProposal.original||aiEvidenceFingerprint(current,question.text)!==aiProposal.fingerprint){setAiError('The answer or evidence changed after this suggestion was prepared. Generate a new suggestion.');setModal(null);return;}change(w=>replaceDraft(w,aiProposal.draft),'Applied an AI suggestion for review');setAiProposal(null);setModal(null);notify('AI suggestion added. Review its wording and evidence before approval.');}
 const inspectorRef=useRef<HTMLElement>(null);const inspectorOriginRef=useRef<HTMLElement|null>(null);
 useEffect(()=>{if(view!=='canvas'||!selectedId||inspectorHidden||!inspectorRef.current)return;const active=document.activeElement;if(active instanceof HTMLElement&&active!==document.body&&!inspectorRef.current.contains(active))inspectorOriginRef.current=active;inspectorRef.current.focus({preventScroll:true});},[selectedId,view,inspectorHidden]);
 function rememberInspectorOrigin(){const active=document.activeElement;if(active instanceof HTMLElement&&active!==document.body&&!inspectorRef.current?.contains(active))inspectorOriginRef.current=active;}
