 function closeInspector(){setInspectorHidden(true);const origin=inspectorOriginRef.current;const target=origin?.isConnected&&origin!==document.body?origin:document.getElementById('canvas-card-search');target?.focus({preventScroll:true});}
 const toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
 useEffect(()=>{setChatSaveOk(saveChat(chatMessages));setChatRecovery(getChatRecoveryStatus());},[chatMessages]);
 useEffect(()=>{setSaveOk(saveWorkspace(workspace));},[workspace]);useEffect(()=>{const fn=()=>setHash(location.hash);window.addEventListener('hashchange',fn);return()=>window.removeEventListener('hashchange',fn);},[]);useEffect(()=>{document.documentElement.dataset.theme=theme;try{localStorage.setItem('maya-theme',theme);}catch{}},[theme]);
 function notify(text:string){setToast(text);if(toastTimer.current)clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),4000);}
 function change(fn:(w:Workspace)=>Workspace,text?:string){setWorkspace(w=>{const result=fn(w);const next={...result,drafts:result.drafts.map(d=>{const before=w.drafts.find(old=>old.id===d.id);return before?recordDraftRevision(before,d,text||'Edited answer',{coalesce:!text}):d;})};if(text)next.activity=[{id:uid('event'),text,at:new Date().toISOString()},...next.activity].slice(0,60);return next;});}
 function navigate(next:View){setCanvasExpanded(false);setView(next);setFilter('All');setSearch('');setSelectedId(null);}
 function ensureCard(kind:CardKind,entityId:string,w:Workspace):[Workspace,string]{const found=w.cards.find(c=>c.kind===kind&&c.entityId===entityId);if(found)return[w,found.id];if(kind==='evidence'){const next=addCaseEvidenceCards(w,[entityId]);const card=next.cards.find(c=>c.kind==='evidence'&&c.entityId===entityId);if(!card)throw new Error('Unknown case-file evidence');return[next,card.id];}const id=uid('card');const x=kind==='question'?40:kind==='draft'||kind==='issue'?800:420;let y=35;const height=kind==='draft'?470:310;const overlaps=(c:CanvasCard)=>Math.abs(c.x-x)<310&&y<c.y+(c.kind==='draft'?470:310)&&y+height>c.y;let occupied=w.cards.filter(overlaps);while(occupied.length){y=Math.max(...occupied.map(c=>c.y+(c.kind==='draft'?470:310)));occupied=w.cards.filter(overlaps);}return [{...w,cards:[...w.cards,{id,kind,entityId,x,y}]},id];}
 function showCard(kind:CardKind,id:string){let target=workspace.cards.find(c=>c.kind===kind&&c.entityId===id)?.id;if(!target){const [next,cid]=ensureCard(kind,id,workspace);target=cid;change(()=>next);}setView('canvas');selectCard(target);setFocusId(target);setFocusKey(n=>n+1);}
 function openCaseEvidence(id:string){if(!findCaseEvidence(id))return;setModal(null);showCard('evidence',id);}
 function addCaseOverview(){const next=addCaseEvidenceCards(workspace,caseOverviewIds);if(next!==workspace)change(()=>next,'Added case-file overview cards');setModal(null);setView('canvas');selectCard(null);setFocusId(null);setFocusKey(n=>n+1);notify('Case-file overview ready. Select a source card to see the full evidence.');}
 function makeDraft(questionId:string,startingPoint?:Draft,preparedDraft?:Draft){const currentWorkspace=workspaceRef.current;const existing=currentWorkspace.drafts.find(d=>d.questionId===questionId);if(existing){showCard('draft',existing.id);notify('Opened the existing answer. Your edits are preserved.');return;}const q=currentWorkspace.questions.find(q=>q.id===questionId);if(!q)return;let draft:Draft;try{draft=preparedDraft||(startingPoint?reuseAnswer(q,startingPoint,currentWorkspace):draftAnswer(q,currentWorkspace.products));}catch{notify('This starting point has changed. Choose a currently reviewed answer or create a fresh draft.');return;}let w={...currentWorkspace,drafts:[...currentWorkspace.drafts,draft]};let cid:string;[w,cid]=ensureCard('draft',draft.id,w);let qid:string;[w,qid]=ensureCard('question',q.id,w);w.links=[...w.links,{id:uid('link'),evidenceOrigin:'generated' as const,source:qid,target:cid}];for(const pid of draft.productIds){let pcid:string;[w,pcid]=ensureCard('product',pid,w);w.links.push({id:uid('link'),evidenceOrigin:'generated' as const,source:pcid,target:cid});}for(const note of mayaNotes.filter(n=>draft.sourceRefs.some(ref=>ref.page===n.source.page&&ref.label===n.source.label&&ref.excerpt===n.source.excerpt))){let nid:string;[w,nid]=ensureCard('note',note.id,w);w.links.push({id:uid('link'),evidenceOrigin:'generated' as const,source:nid,target:cid});}change(()=>w,preparedDraft?'Created an AI suggestion for review':startingPoint?'Reused a reviewed answer as a new draft':'Created an evidence-template draft');setView('canvas');selectCard(cid);setFocusId(cid);setFocusKey(n=>n+1);notify(startingPoint?'Reviewed wording reused. Check this follower’s context before approving.':'Draft and supporting cards prepared. Review the decision before publishing.');}
 function replaceDraft(w:Workspace,fresh:Draft):Workspace{
  const card=w.cards.find(c=>c.kind==='draft'&&c.entityId===fresh.id);
  // Older note links were deliberately attached by hand, before generated note links existed.
  const manualNoteLinks=card?w.links.filter(l=>l.target===card.id&&l.evidenceOrigin!=='generated'&&w.cards.find(c=>c.id===l.source)?.kind==='note'):[];
  const noteSources=manualNoteLinks.flatMap(l=>{const from=w.cards.find(c=>c.id===l.source);const note=mayaNotes.find(n=>n.id===from?.entityId);return note?[note.source]:[];});
  const sourceRefs=[...fresh.sourceRefs];for(const ref of noteSources)if(!sourceRefs.some(s=>s.page===ref.page&&s.label===ref.label&&s.excerpt===ref.excerpt))sourceRefs.push(ref);
  let next={...w,drafts:w.drafts.map(d=>d.id===fresh.id?{...fresh,history:d.history,sourceRefs}:d)};if(!card)return next;
  next.links=next.links.filter(l=>{if(l.target!==card.id)return true;const from=next.cards.find(c=>c.id===l.source);return from?.kind!=='product'&&!(from?.kind==='note'&&l.evidenceOrigin==='generated');});
  for(const productId of fresh.productIds){let source:string;[next,source]=ensureCard('product',productId,next);next.links.push({id:uid('link'),evidenceOrigin:'generated',source,target:card.id});}
  for(const note of mayaNotes.filter(n=>fresh.sourceRefs.some(ref=>ref.page===n.source.page&&ref.label===n.source.label&&ref.excerpt===n.source.excerpt))){let source:string;[next,source]=ensureCard('note',note.id,next);if(!next.links.some(l=>l.source===source&&l.target===card.id))next.links.push({id:uid('link'),evidenceOrigin:'generated',source,target:card.id});}
  return next;
 }
 function updateDraft(id:string,patch:Partial<Draft>){change(w=>({...w,drafts:w.drafts.map(d=>d.id===id?{...d,...patch,status:'draft',approvedAt:undefined,publishedAt:undefined,updatedAt:new Date().toISOString()}:d)}));}
 function approveDraft(id:string,publish=false):boolean{const draft=workspace.drafts.find(d=>d.id===id);if(!draft)return false;const problems=validateDraft(draft,workspace);if(problems.length){notify(problems[0]);return false;}if(publish){const result=commitPublication(workspace,id);if(!result.ok){notify(result.error);return false;}setWorkspace(result.workspace);setSaveOk(true);notify('Advice card published in this local prototype.');return true;}const now=new Date().toISOString();change(w=>({...w,drafts:w.drafts.map(d=>d.id===id?{...d,status:'approved',approvedAt:d.approvedAt||now,updatedAt:now}:d)}),'Approved an answer locally');notify('Approved. The answer is ready to publish.');return true;}

 function regenerateAnswer(keepWording:boolean){const previous=workspace.drafts.find(d=>d.id===regenerateId);const question=workspace.questions.find(q=>q.id===previous?.questionId);if(!previous||!question)return;const fresh={...draftAnswer(question,workspace.products),id:previous.id,createdAt:previous.createdAt,...(keepWording?{title:previous.title,text:previous.text,decision:previous.decision,mode:previous.mode,ai:previous.ai}:{})};change(w=>replaceDraft(w,fresh),keepWording?'Refreshed evidence and kept edited wording':'Regenerated from current evidence');setModal(null);notify('Earlier wording saved in Answer history. Review the updated answer.');}
 function restoreAnswer(id:string,revisionId:string){change(w=>({...w,drafts:w.drafts.map(d=>d.id===id?restoreDraftRevision(d,revisionId):d)}),'Restored earlier answer wording');notify('Wording restored with current evidence. Review it before approval.');}
 function addFeedbackQuestion(text:string):boolean{const clean=text.trim().slice(0,2000);if(!clean)return false;const q={id:uid('q'),handle:'@feedback',text:clean,intent:groupQuestion(clean),productIds:detectQuestionProducts(clean,workspace.products),source:{page:0,label:'Follower feedback reviewed in this workspace',excerpt:clean},addedAt:new Date().toISOString()};const next={...workspace,questions:[q,...workspace.questions],activity:[{id:uid('event'),text:'Added a follow-up from follower feedback',at:new Date().toISOString()},...workspace.activity].slice(0,60)};if(!saveWorkspace(next)){setSaveOk(false);return false;}setWorkspace(next);setSaveOk(true);navigate('questions');notify('Follow-up added and saved with the follower’s clarification.');return true;}
 function publishLink(draft:Draft){try{const issues=validateDraft(draft,workspace);if(issues.length){notify(issues[0]);return;}const advice=toPublishedAdvice(draft,workspace);setShareLink(shareUrl(advice));setModal('share');}catch(error){notify(error instanceof Error?error.message:'The answer could not be prepared for sharing.');}}
 function connect(source:string,target:string){if(source===target||workspace.links.some(l=>l.source===source&&l.target===target))return;change(w=>{let drafts=w.drafts;const from=w.cards.find(c=>c.id===source),to=w.cards.find(c=>c.id===target);if(to?.kind==='draft'&&from?.kind==='product'){const p=w.products.find(p=>p.id===from.entityId);if(p)drafts=drafts.map(d=>d.id===to.entityId?{...d,productIds:[...new Set([...d.productIds,p.id])],sourceRefs:d.sourceRefs.some(s=>s.label===p.source.label)?d.sourceRefs:[...d.sourceRefs,p.source],productRevisions:{...d.productRevisions,[p.id]:d.productRevisions[p.id]??p.revision},status:'draft',approvedAt:undefined,publishedAt:undefined}:d);}if(to?.kind==='draft'&&from?.kind==='note'){const note=mayaNotes.find(n=>n.id===from.entityId);if(note)drafts=drafts.map(d=>d.id===to.entityId?{...d,sourceRefs:d.sourceRefs.some(s=>s.page===note.source.page&&s.label===note.source.label&&s.excerpt===note.source.excerpt)?d.sourceRefs:[...d.sourceRefs,note.source],status:'draft',approvedAt:undefined,publishedAt:undefined,updatedAt:new Date().toISOString()}:d);}return {...w,drafts,links:[...w.links,{id:uid('link'),evidenceOrigin:'manual' as const,source,target}]};},'Connected supporting cards');}
 function disconnect(id:string){change(w=>{const link=w.links.find(l=>l.id===id);const from=w.cards.find(c=>c.id===link?.source);const to=w.cards.find(c=>c.id===link?.target);let drafts=w.drafts;if(from?.kind==='product'&&to?.kind==='draft'){const p=w.products.find(p=>p.id===from.entityId);drafts=drafts.map(d=>d.id===to.entityId?{...d,productIds:d.productIds.filter(pid=>pid!==from.entityId),sourceRefs:p?d.sourceRefs.filter(ref=>!(ref.label===p.source.label&&ref.page===p.source.page)):d.sourceRefs,status:'draft',approvedAt:undefined,publishedAt:undefined}:d);}if(from?.kind==='note'&&to?.kind==='draft'){const note=mayaNotes.find(n=>n.id===from.entityId);if(note)drafts=drafts.map(d=>d.id===to.entityId?{...d,sourceRefs:d.sourceRefs.filter(ref=>!(ref.page===note.source.page&&ref.label===note.source.label&&ref.excerpt===note.source.excerpt)),status:'draft',approvedAt:undefined,publishedAt:undefined,updatedAt:new Date().toISOString()}:d);}return {...w,drafts,links:w.links.filter(l=>l.id!==id)};},'Removed an evidence connection');}
 async function sendChat(text:string,retry=false){
  const trimmed=text.trim().slice(0,2000);if(!trimmed||aiRequestRef.current)return;const at=new Date().toISOString();
  if(!aiEnabled||!aiStatus.configured){setChatMessages(history=>{const user:ChatMessage={id:uid('chat-user'),role:'user',text:trimmed,createdAt:at};const reply=respondToChat(trimmed,workspace,history,view==='canvas'?selected:undefined);return [...history,user,{...reply,origin:'local' as const,id:uid('chat-maya'),role:'assistant' as const,createdAt:at}].slice(-CHAT_HISTORY_LIMIT);});return;}
  const initial=workspaceRef.current;const selection=view==='canvas'?selected:undefined;const selectionId=selectionRef.current;const fingerprint=aiEvidenceFingerprint(initial,trimmed,selection);const history=retry?chatMessages.slice(0,-1):chatMessages;
  if(!retry)setChatMessages(previous=>[...previous,{id:uid('chat-user'),role:'user',text:trimmed,createdAt:at} as ChatMessage].slice(-CHAT_HISTORY_LIMIT));
  const controller=new AbortController();aiRequestRef.current=controller;setAiPending('chat');setAiError('');setFailedChat('');
  try{const request=buildAiRequest('chat',trimmed,initial,history,selection);const response=await requestAiAnswer(request,controller.signal);if(aiRequestRef.current!==controller)return;
   const current=workspaceRef.current;if(selectionRef.current!==selectionId||fingerprint!==aiEvidenceFingerprint(current,trimmed,selection))throw new Error('The selected card or evidence changed while AI was answering. Send the question again using the current evidence.');
   const reply=validateAiChat(response,request,current);setChatMessages(previous=>[...previous,{...reply,id:uid('chat-ai'),role:'assistant' as const,origin:'ai' as const,aiModel:response.model,createdAt:new Date().toISOString()}].slice(-CHAT_HISTORY_LIMIT));
  }catch(error){if(aiRequestRef.current===controller){setAiError(error instanceof Error?error.message:'AI could not answer. Check the connection and try again.');setFailedChat(trimmed);}}
  finally{if(aiRequestRef.current===controller){aiRequestRef.current=null;setAiPending(null);}}
 }

 function clearChatHistory(){cancelAi();setAiError('');setFailedChat('');if(clearSavedChat()){setChatMessages([]);setChatSaveOk(true);}else setChatSaveOk(false);setChatRecovery(getChatRecoveryStatus());}
