 function addChatQuestion(text:string){const clean=text.trim().slice(0,2000);if(!clean)return;const q={id:uid('q'),handle:'@chat-note',text:clean,intent:groupQuestion(clean),productIds:detectQuestionProducts(clean,workspace.products),source:{page:0,label:'Question reviewed in chat',excerpt:clean},addedAt:new Date().toISOString()};change(w=>({...w,questions:[q,...w.questions]}),'Added a reviewed question from chat');setChatOpen(false);navigate('questions');notify('Question added. Open it to prepare and review an answer.');}
