 function voiceCommand(command:string):VoiceCommandResult{const action=parseVoiceCommand(command,workspace.questions,selected?.kind==='question'?selected.entityId:undefined);if(action.type==='unsupported')return {ok:false,message:action.message};if(action.type==='inspect')return personaReply(action.topic,workspace,selected);if(action.type==='navigate'){navigate(action.view);const replies:Record<View,string>={canvas:'The canvas is open. Start with a question, then connect the evidence behind the answer.',questions:`The inbox is open with ${workspace.questions.length} questions. Similar questions can share a theme; each person keeps their own context.`,knowledge:'The knowledge shelf is open. Product facts and recorded judgements are here; missing details still need a source.',reports:'The evidence report is open. '+personaReply('issues',workspace).message,published:'The approved-advice view is open. These are local review records; shared copies keep the wording they were published with.',feedback:'Follower feedback is open. Review the saved clarifications before adding a follow-up question.'};return {ok:true,message:replies[action.view]};}const q=workspace.questions.find(q=>q.id===action.questionId);const existing=workspace.drafts.find(d=>d.questionId===action.questionId);prepareDraft(action.questionId);return {ok:true,message:existing?`There is already an answer for ${q?.handle||'this question'}. I’ve opened it and kept your edits. Use “Explain this card” to check what needs attention.`:aiEnabled&&aiStatus.configured?'AI is preparing the draft. Follow its progress on the canvas and review it before approval.':`The draft for ${q?.handle||'this question'} is prepared from the recorded notes. Check the evidence and wording before approval. A neat sentence does not fill a missing fact.`};}
