 function runChecks(){change(w=>{const issues=runEvidenceChecks(w);const issueIds=new Set(issues.map(issue=>issue.id));const cards=w.cards.filter(card=>card.kind!=='issue'||issueIds.has(card.entityId));const cardIds=new Set(cards.map(card=>card.id));return {...w,issues,cards,links:w.links.filter(link=>cardIds.has(link.source)&&cardIds.has(link.target))};},'Ran the case-file evidence checks');notify('Checked the supplied case-file records. This is a focused check, not a general document audit.');}
