 const selectedSpeech=selected?.kind==='evidence'?(()=>{const evidence=findCaseEvidence(selected.entityId);return evidence?`${evidence.title}. ${caseEvidenceText(evidence)}`:'';})():selected?.kind==='question'?workspace.questions.find(q=>q.id===selected.entityId)?.text:selected?.kind==='draft'?(currentDraft?`${currentDraft.text}${currentDraft.decision?` Maya’s call: ${currentDraft.decision.verdict}. Who this is for: ${currentDraft.decision.suits}. When to skip it: ${currentDraft.decision.skipIf}. What still needs checking: ${currentDraft.decision.unknowns}`:''}`:''):selected?.kind==='product'?(()=>{const p=workspace.products.find(p=>p.id===selected.entityId);return p?`${p.name}, ${p.price} pounds. ${p.note}`:'';})():selected?.kind==='note'?mayaNotes.find(n=>n.id===selected.entityId)?.text:selected?.kind==='issue'?(()=>{const issue=workspace.issues.find(i=>i.id===selected.entityId);return issue?`${issue.title}. Status: ${issue.status}. ${issue.status==='Resolved'?'Original finding: ':''}${issue.description}${issue.status==='Resolved'?` Recorded resolution: ${issue.resolution||'No resolution detail supplied.'}`:''}`:'';})():'';
