 {view==='reports'&&<><div className="list-toolbar"><div className="report-intro"><span className="eyebrow">EVIDENCE REVIEW</span><p>Focused checks of the supplied records. Findings retain their original evidence.</p></div><div className="button-row"><button className="secondary small" onClick={runChecks}><ShieldCheck size={15}/>Run checks</button><button className="primary small" onClick={()=>{downloadText('goodcall-evidence-report.md',buildReport(workspace));notify('Evidence report downloaded.');}}><ArrowDownToLine size={15}/>Export report</button></div></div><div className="report-stats"><div><span>OPEN FINDINGS</span><strong>{openIssues.length.toString().padStart(2,'0')}</strong><small>Need a decision or more evidence</small></div><div><span>MISSING MATERIALS</span><strong>{openIssues.filter(i=>i.kind==='Missing material').length.toString().padStart(2,'0')}</strong><small>Information to complete the picture</small></div><div><span>RESOLVED</span><strong>{workspace.issues.filter(i=>i.status==='Resolved').length.toString().padStart(2,'0')}</strong><small>With a recorded explanation</small></div></div><div className="filter-tabs">{['All','Audience advice','Case-file report','Missing material','Resolved'].map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f}</button>)}</div><div className="issues-list">{workspace.issues.filter(i=>filter==='All'||i.area===filter||i.kind===filter||(filter==='Resolved'&&i.status==='Resolved')).map(i=><IssueReport key={i.id} issue={i} onCanvas={()=>showCard('issue',i.id)} onUpdate={patch=>change(w=>({...w,issues:w.issues.map(x=>x.id===i.id?{...x,...patch}:x)}),patch.status==='Resolved'?`Recorded resolution: ${i.title}`:undefined)}/>)}</div><p className="report-disclaimer">A recorded resolution does not supply missing product facts. Recommendations still need supported evidence before approval.</p></>}
